In C, arrays can be manipulated in multiple ways. Below are various methods related to arrays, including declaration, initialization, traversal, searching, sorting, and other operations.

---

### **1. Declaration and Initialization**
```c
int arr1[5];  // Declaration without initialization
int arr2[5] = {1, 2, 3, 4, 5};  // Initialization with values
int arr3[] = {10, 20, 30, 40};  // Compiler determines size
```

---

### **2. Input and Output of Arrays**
```c
#include <stdio.h>

int main() {
    int arr[5];

    // Input
    printf("Enter 5 elements: ");
    for(int i = 0; i < 5; i++) {
        scanf("%d", &arr[i]);
    }

    // Output
    printf("Array elements: ");
    for(int i = 0; i < 5; i++) {
        printf("%d ", arr[i]);
    }

    return 0;
}
```

---

### **3. Traversing an Array**
```c
void traverse(int arr[], int size) {
    for(int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}
```

---

### **4. Searching in an Array**
#### **(a) Linear Search**
```c
int linearSearch(int arr[], int size, int key) {
    for(int i = 0; i < size; i++) {
        if(arr[i] == key)
            return i;  // Return index
    }
    return -1;  // Not found
}
```

#### **(b) Binary Search (Array must be sorted)**
```c
int binarySearch(int arr[], int size, int key) {
    int low = 0, high = size - 1, mid;
    while(low <= high) {
        mid = (low + high) / 2;
        if(arr[mid] == key)
            return mid;
        else if(arr[mid] < key)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1;
}
```

---

### **5. Sorting an Array**
#### **(a) Bubble Sort**
```c
void bubbleSort(int arr[], int size) {
    for(int i = 0; i < size - 1; i++) {
        for(int j = 0; j < size - i - 1; j++) {
            if(arr[j] > arr[j+1]) {
                // Swap
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}
```

#### **(b) Selection Sort**
```c
void selectionSort(int arr[], int size) {
    for(int i = 0; i < size - 1; i++) {
        int minIndex = i;
        for(int j = i + 1; j < size; j++) {
            if(arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        // Swap
        int temp = arr[minIndex];
        arr[minIndex] = arr[i];
        arr[i] = temp;
    }
}
```

